  repoRoot,
  instance,
  ports,
  selection,
  spawnProcess,
  stopGraceMs = STOP_GRACE_MS,
  // Injectable so the tests never write into the real `.urbo/` of whoever runs them.
  logFile = (name) => logFileFor(instance, name),
  platform = process.platform,
  killProcess = killTree,
  stopSignal = listenForStopSignal,
  probe = answersOnPort,
  now = Date.now,
  sleep = (ms) => delay(ms),
}) {
